class Solution {
 public boolean isSubtree(TreeNode root,TreeNode subRoot){if(subRoot==null)return true;if(root==null)return false;return same(root,subRoot)||isSubtree(root.left,subRoot)||isSubtree(root.right,subRoot);}
 private boolean same(TreeNode a,TreeNode b){if(a==null||b==null)return a==b;return a.val==b.val&&same(a.left,b.left)&&same(a.right,b.right);}
}

class Solution {
 public int findUnsortedSubarray(int[] a){int n=a.length,l=0;while(l<n-1&&a[l]<=a[l+1])l++;if(l==n-1)return 0;int r=n-1;while(r>0&&a[r-1]<=a[r])r--;int lo=Integer.MAX_VALUE,hi=Integer.MIN_VALUE;for(int i=l;i<=r;i++){lo=Math.min(lo,a[i]);hi=Math.max(hi,a[i]);}while(l>0&&a[l-1]>lo)l--;while(r<n-1&&a[r+1]<hi)r++;return r-l+1;}
}

