 def minDistance(self,word1,word2):
  dp=[0]*(len(word2)+1)
  for a in word1:
   diagonal=0
   for j,b in enumerate(word2,1):
    old=dp[j];dp[j]=diagonal+1 if a==b else max(dp[j],dp[j-1]);diagonal=old
  return len(word1)+len(word2)-2*dp[-1]

class Solution {
 public int minDistance(String a,String b){int[]dp=new int[b.length()+1];for(int i=0;i<a.length();i++){int diagonal=0;for(int j=1;j<=b.length();j++){int old=dp[j];dp[j]=a.charAt(i)==b.charAt(j-1)?diagonal+1:Math.max(dp[j],dp[j-1]);diagonal=old;}}return a.length()+b.length()-2*dp[b.length()];}
}

