class Solution {
 public List<Integer> preorder(Node root){List<Integer>out=new ArrayList<>();dfs(root,out);return out;}
 private void dfs(Node n,List<Integer>out){if(n==null)return;out.add(n.val);for(Node c:n.children)dfs(c,out);}
}

