from collections import Counter
class Solution:
 def findLHS(self,nums):
  f=Counter(nums);return max((f[x]+f[x+1] for x in f if x+1 in f),default=0)

import java.util.*;
class Solution {
 public int findLHS(int[]nums){Map<Integer,Integer>f=new HashMap<>();for(int x:nums)f.put(x,f.getOrDefault(x,0)+1);int best=0;for(int x:f.keySet())if(f.containsKey(x+1))best=Math.max(best,f.get(x)+f.get(x+1));return best;}
}

class Solution:
 def maxCount(self,m,n,ops):
  return min((a for a,_ in ops),default=m)*min((b for _,b in ops),default=n)

class Solution {
 public int maxCount(int m,int n,int[][]ops){int rows=m,cols=n;for(int[]op:ops){rows=Math.min(rows,op[0]);cols=Math.min(cols,op[1]);}return rows*cols;}
}

class Solution:
 def findRestaurant(self,list1,list2):
  idx={s:i for i,s in enumerate(list1)};best=float('inf');out=[]
  for j,s in enumerate(list2):
   if s not in idx:continue
   v=idx[s]+j
   if v<best:best,out=v,[s]
   elif v==best:out.append(s)
  return out

import java.util.*;
class Solution {
 public String[] findRestaurant(String[]a,String[]b){Map<String,Integer>idx=new HashMap<>();for(int i=0;i<a.length;i++)idx.put(a[i],i);int best=Integer.MAX_VALUE;List<String>out=new ArrayList<>();for(int j=0;j<b.length;j++){Integer i=idx.get(b[j]);if(i==null)continue;int v=i+j;if(v<best){best=v;out.clear();out.add(b[j]);}else if(v==best)out.add(b[j]);}return out.toArray(new String[0]);}
}

class Solution:
 def canPlaceFlowers(self,flowerbed,n):
  planted=0
  for i,x in enumerate(flowerbed):
   if x==0 and (i==0 or flowerbed[i-1]==0) and (i==len(flowerbed)-1 or flowerbed[i+1]==0):
    flowerbed[i]=1;planted+=1
    if planted>=n:return True
  return planted>=n

class Solution {
 public boolean canPlaceFlowers(int[]bed,int n){int planted=0;for(int i=0;i<bed.length;i++)if(bed[i]==0&&(i==0||bed[i-1]==0)&&(i==bed.length-1||bed[i+1]==0)){bed[i]=1;if(++planted>=n)return true;}return planted>=n;}
}
